from pathlib import Path

queue_path = Path('deduper/family_recertification_queue.py')
text = queue_path.read_text()
old = '''    def _create_current_schema(self) -> None:\n        # Create only the base tables first. Existing prerelease databases may\n'''
new = '''    def _create_current_schema(self) -> None:\n        self._repair_malformed_current_schema()\n        # Create only the base tables first. Existing prerelease databases may\n'''
if old not in text:
    raise SystemExit('schema creation anchor missing')
text = text.replace(old, new, 1)
anchor = '''    def _create_current_schema(self) -> None:\n'''
method = '''    def _repair_malformed_current_schema(self) -> None:\n        if not self._table_exists("family_recertification_jobs"):\n            return\n        columns = {\n            str(row["name"])\n            for row in self.database.connection.execute(\n                "PRAGMA table_info(family_recertification_jobs)"\n            ).fetchall()\n        }\n        required_identity = {"id", "deleted_key", "protected_key"}\n        if required_identity.issubset(columns):\n            return\n\n        row_count = int(\n            self.database.connection.execute(\n                "SELECT COUNT(*) AS count FROM family_recertification_jobs"\n            ).fetchone()["count"]\n        )\n        member_count = 0\n        if self._table_exists("family_recertification_members"):\n            member_count = int(\n                self.database.connection.execute(\n                    "SELECT COUNT(*) AS count FROM family_recertification_members"\n                ).fetchone()["count"]\n            )\n        if row_count or member_count:\n            missing = ", ".join(sorted(required_identity - columns))\n            present = ", ".join(sorted(columns)) or "none"\n            raise RuntimeError(\n                "Malformed prerelease family recertification schema contains data; "\n                f"cannot safely infer missing columns ({missing}). Present columns: {present}"\n            )\n\n        # Empty prerelease tables carry no recertification work. Rebuild them\n        # atomically instead of trying to ALTER an incompatible table shape.\n        self.database.connection.execute(\n            "DROP TABLE IF EXISTS family_recertification_members"\n        )\n        self.database.connection.execute(\n            "DROP TABLE family_recertification_jobs"\n        )\n\n'''
pos = text.index(anchor)
text = text[:pos] + method + text[pos:]
queue_path.write_text(text)

test_path = Path('tests/test_family_recertification_schema_migration.py')
test = test_path.read_text()
insert = '''\n    def test_empty_malformed_modern_tables_are_rebuilt_canonically(self) -> None:\n        with tempfile.TemporaryDirectory() as directory:\n            db = CertifiedDatabase(Path(directory) / "deduper.sqlite3")\n            with db.connection:\n                db.connection.executescript("""\n                    CREATE TABLE family_recertification_jobs (\n                        id INTEGER PRIMARY KEY AUTOINCREMENT\n                    );\n                    CREATE TABLE family_recertification_members (\n                        recertification_id INTEGER, asset_key TEXT\n                    );\n                """)\n            FamilyRecertificationQueue(db)\n            columns = {row['name'] for row in db.connection.execute(\n                "PRAGMA table_info(family_recertification_jobs)"\n            )}\n            self.assertTrue({'id', 'deleted_key', 'protected_key', 'status'} <= columns)\n            member_columns = {row['name'] for row in db.connection.execute(\n                "PRAGMA table_info(family_recertification_members)"\n            )}\n            self.assertEqual(\n                member_columns,\n                {'recertification_id', 'priority', 'asset_key'},\n            )\n            db.close()\n\n    def test_nonempty_malformed_modern_table_fails_without_dropping_data(self) -> None:\n        with tempfile.TemporaryDirectory() as directory:\n            db = CertifiedDatabase(Path(directory) / "deduper.sqlite3")\n            with db.connection:\n                db.connection.executescript("""\n                    CREATE TABLE family_recertification_jobs (\n                        id INTEGER PRIMARY KEY AUTOINCREMENT\n                    );\n                    INSERT INTO family_recertification_jobs DEFAULT VALUES;\n                """)\n            with self.assertRaisesRegex(RuntimeError, 'contains data'):\n                FamilyRecertificationQueue(db)\n            count = db.connection.execute(\n                "SELECT COUNT(*) AS count FROM family_recertification_jobs"\n            ).fetchone()['count']\n            self.assertEqual(count, 1)\n            db.close()\n'''
needle = '\n\nif __name__ == \'__main__\':\n'
if needle not in test:
    raise SystemExit('test insertion anchor missing')
test = test.replace(needle, insert + needle, 1)
test_path.write_text(test)
